export interface PriceEntry {
  site: string;
  price: number;
  mrp: number;
  link: string;
  inStock: boolean;
  delivery: string;
  color: string;
}

export interface Product {
  id: string;
  name: string;
  brand: string;
  category: string;
  image: string; // real image URL
  tag?: string;
  prices: PriceEntry[];
  rating: number;
  reviews: number;
  description: string;
  highlights: string[];
}

export const SITES = ["1mg","PharmEasy","Netmeds","Apollo","HealthKart","Amazon","Flipkart"];

const mk = (
  id: string, name: string, brand: string, category: string,
  image: string, tag: string|undefined,
  priceData: [string, number, number][], // [site, price, mrp]
  rating: number, reviews: number,
  description: string, highlights: string[]
): Product => ({
  id, name, brand, category, image, tag,
  prices: priceData.map(([site, price, mrp]) => ({
    site, price, mrp,
    link: `https://www.${site === '1mg' ? '1mg.com/search/all?name=' : site === 'PharmEasy' ? 'pharmeasy.in/search/all?name=' : site === 'Netmeds' ? 'netmeds.com/catalogsearch/result?q=' : site === 'Apollo' ? 'apollopharmacy.in/search-medicines/' : site === 'HealthKart' ? 'healthkart.com/search?q=' : site === 'Amazon' ? 'amazon.in/s?k=' : 'flipkart.com/search?q='}${encodeURIComponent(name)}`,
    inStock: Math.random() > 0.15,
    delivery: ["Today","Tomorrow","2 days","3 days"][Math.floor(Math.random()*4)],
    color: {
      "1mg":"#e53e3e","PharmEasy":"#3182ce","Netmeds":"#805ad5",
      "Apollo":"#2b6cb0","HealthKart":"#dd6b20","Amazon":"#f6ad55","Flipkart":"#4299e1"
    }[site] || "#888"
  })),
  rating, reviews, description, highlights
});

